1	import { Router } from "express";
2	import { z } from "zod";
3	import type { Db } from "@paperclipai/db";
4	import { assertBoard, assertCompanyAccess } from "./authz.js";
5	import { inboxDismissalService, logActivity } from "../services/index.js";
6	import { expressHandler } from "../http/express-adapter.js";
7	import type { Handler } from "../http/types.js";
8	import type { StorageService } from "../storage/types.js";
9	
10	const inboxDismissalSchema = z.object({
11	  itemKey: z.string().trim().min(1).regex(/^(approval|join|run):.+$/, "Unsupported inbox item key"),
12	});
13	
14	function buildHandlers(db: Db) {
15	  const svc = inboxDismissalService(db);
16	
17	  // server/src/routes/inbox-dismissals.ts:16
18	  const getInboxDismissals: Handler = async (ctx) => {
19	    const companyId = ctx.param("companyId") ?? "";
20	    assertCompanyAccess(ctx, companyId);
21	    assertBoard(ctx);
22	    const dismissals = await svc.list(companyId, (ctx.actor as { userId: string }).userId);
23	    return Response.json(dismissals);
24	  };
25	
26	  // server/src/routes/inbox-dismissals.ts:31
27	  const postInboxDismissal: Handler = async (ctx) => {
28	    const companyId = ctx.param("companyId") ?? "";
29	    assertCompanyAccessCtx(ctx, companyId);
30	    if (ctx.actor?.type !== "board") {
31	      return Response.json({ error: "Board authentication required" }, { status: 403 });
32	    }
33	    if (!ctx.actor.userId) {
34	      return Response.json({ error: "Board user context required" }, { status: 403 });
35	    }
36	
37	    const body = await ctx.json();
38	    const parsed = inboxDismissalSchema.parse(body);
39	
40	    const dismissal = await svc.dismiss(companyId, ctx.actor.userId, parsed.itemKey, new Date());
41	
42	    // ctx.actor lacks `runId`; log with null runId.
43	    // TODO(cloudflare): thread runId through ActorContext.
44	    await logActivity(db, {
45	      companyId,
46	      actorType: "user",
47	      actorId: ctx.actor.userId,
48	      agentId: null,
49	      runId: null,
50	      action: "inbox.dismissed",
51	      entityType: "company",
52	      entityId: companyId,
53	      details: {
54	        userId: ctx.actor.userId,
55	        itemKey: dismissal.itemKey,
56	        dismissedAt: dismissal.dismissedAt,
57	      },
58	    });
59	
60	    return Response.json(dismissal, { status: 201 });
61	  };
62	
63	  return { getInboxDismissals, postInboxDismissal };
64	}
65	
66	export function inboxDismissalRoutes(db: Db) {
67	  const router = Router();
68	  const { getInboxDismissals, postInboxDismissal } = buildHandlers(db);
69	
70	  const storageSentinel = new Proxy({} as StorageService, {
71	    get(_target, prop) {
72	      throw new Error(`inboxDismissal handler unexpectedly accessed storage.${String(prop)}`);
73	    },
74	  });
75	  const deps = { db, storage: storageSentinel };
76	
77	  router.get("/companies/:companyId/inbox-dismissals", expressHandler(getInboxDismissals, deps));
78	  router.post("/companies/:companyId/inbox-dismissals", expressHandler(postInboxDismissal, deps));
79	
80	  return router;
81	}
